{
  "decision-equipment-deposit-refund-terms": "WITH assessed AS (SELECT r.return_code, n.source_id, r.held_cents, MIN(r.held_cents, MAX(0, r.damage_cents - n.allowance_cents)) AS retained_cents FROM equipment_returns AS r JOIN terms_notices AS n ON n.fleet_code = r.fleet_code AND n.start_day = (SELECT MAX(t.start_day) FROM terms_notices AS t WHERE t.fleet_code = r.fleet_code AND t.start_day <= r.intake_day) WHERE r.damage_cents IS NOT NULL) SELECT return_code, source_id, retained_cents, held_cents - retained_cents AS refund_cents FROM assessed ORDER BY return_code ASC",
  "decision-estimate-paired-crossover-carryover": "SELECT COUNT(*) AS matched_blocks, AVG((ab.period_one + ab.period_two) - (ba.period_one + ba.period_two)) AS carryover_units FROM rig_readings AS ab JOIN rig_readings AS ba ON ba.block_id = ab.block_id WHERE ab.sequence = 'AB' AND ba.sequence = 'BA'",
  "decision-estimate-unreported-drive-failures": "WITH history AS (SELECT model_code, SUM(expiry_count - first_count) AS later_failures, SUM(first_count) AS first_failures FROM drive_cohort WHERE cohort_stage = 'history' GROUP BY model_code), ratios AS (SELECT c.model_code, c.repair_cents, c.first_count * h.later_failures AS numerator, h.first_failures AS denominator FROM drive_cohort AS c JOIN history AS h ON h.model_code = c.model_code WHERE c.cohort_stage = 'current'), estimates AS (SELECT model_code, repair_cents, numerator / denominator + (numerator % denominator > 0) AS additional_failures FROM ratios) SELECT model_code, additional_failures, additional_failures * repair_cents AS provision_cents FROM estimates ORDER BY model_code ASC",
  "decision-evidenced-meter-credit-export": "WITH ranked AS (SELECT invoice_code, source_id, final_units, ROW_NUMBER() OVER (PARTITION BY invoice_code ORDER BY note_day DESC, source_id COLLATE BINARY DESC) AS rn FROM meter_evidence WHERE note_state = 'signed' AND note_day <= '2026-06-30'), lines AS (SELECT printf('%s,%d,%s', i.invoice_code, (i.billed_units - e.final_units) * i.unit_cents, e.source_id) || char(10) AS line FROM usage_invoice AS i JOIN ranked AS e ON e.invoice_code = i.invoice_code AND e.rn = 1 WHERE i.billed_units > e.final_units ORDER BY i.invoice_code COLLATE BINARY ASC) SELECT 'invoice_code,credit_cents,source_id' || char(10) || COALESCE(group_concat(line, ''), '') AS csv_text FROM lines"
}
